"""Generate a deterministic bank of 1000 verified question variants."""
import json
from itertools import product
from pathlib import Path

CARDS = [
    (['как начать', 'что делать сначала', 'я впервые в игре', 'с чего начать экспедицию'], 'Подтверди готовность в лобби, осмотрись, затем выбери полезную постройку с учётом общего запаса команды.', ['start']),
    (['как двигаться', 'какие кнопки движения', 'как ходить', 'управление персонажем'], 'WASD отвечает за движение, Shift — за бег, Space — за прыжок, F — за фонарик.', ['controls']),
    (['как построить бур', 'где ставить бур', 'почему бур не строится', 'что делает бур'], 'Бур ставится на свободную ресурсную клетку рядом с игроком и добывает ресурс именно этой клетки.', ['drill']),
    (['что добывает бур', 'может ли бур добыть руду', 'как получить медь', 'откуда железо'], 'Буры добывают железо, медь, воду или серу в зависимости от ресурса клетки; руду они не добывают.', ['drill','resources']),
    (['как забрать добычу', 'где ресурсы из бура', 'бур уже накопил ресурс', 'как опустошить бур'], 'Наведи указатель на бур и взаимодействуй с ним, чтобы перенести накопленную добычу в рюкзак.', ['drill','inventory']),
    (['зачем нужен склад', 'как работает склад', 'куда нести ресурсы', 'общий запас команды'], 'Склад увеличивает вместимость команды; при взаимодействии с ним ресурсы из рюкзака переходят в общий запас.', ['warehouse']),
    (['как получить кислород', 'как работает генератор', 'почему не растёт кислород', 'куда нести воду'], 'Генератор расходует воду из своего запаса и повышает общий oxygen_percent планеты.', ['oxygen']),
    (['как снабжать генератор', 'склад передаёт воду', 'автоподача воды', 'почему генератор без воды'], 'Склад автоматически снабжает водой генераторы той же команды только на соседних клетках.', ['oxygen','warehouse']),
    (['как снести постройку', 'можно удалить бур', 'вернутся ли ресурсы', 'ошибся с постройкой'], 'Открой постройку клавишей E и выбери снос; оплаченная стоимость возвращается команде.', ['building']),
    (['как вернуться на базу', 'я потерялся', 'где посадка', 'кнопка к базе'], 'Кнопка «К базе» возвращает персонажа к базе или к точке посадки.', ['navigation']),
    (['как включить вид планеты', 'как работает обзор', 'как отдалить камеру', 'вид сверху'], 'Tab открывает обзор планеты; колёсико меняет расстояние, а перетаскивание мышью и стрелки вращают вид.', ['controls','camera']),
    (['как дела', 'кто ты', 'как тебя зовут', 'что ты умеешь'], 'Я Марсик, локальный помощник экспедиции: могу вести диалог, объяснять игровые правила и помогать выбрать следующий шаг.', ['social']),
    (['есть ли ловушки', 'какие враги', 'можно получить урон', 'опасно ли идти'], 'Подтверждённых данных о ловушках или врагах в текущем состоянии нет; не следует выдумывать такие механики.', ['safety']),
    (['сколько стоит постройка', 'хватит ли ресурсов', 'цена бура', 'стоимость генератора'], 'Актуальные рецепты находятся в config текущего состояния; сравни их с team_storage команды.', ['recipes']),
    (['почему не могу строить', 'клетка недоступна', 'слишком далеко строить', 'место занято'], 'Сервер проверяет расстояние, тип клетки, наличие ресурсов и отсутствие другой постройки на выбранном месте.', ['building']),
    (['что в рюкзаке', 'мой инвентарь', 'сколько могу нести', 'рюкзак заполнен'], 'Текущий inventory показывает личные ресурсы; точный лимит берётся из config текущего состояния.', ['inventory']),
    (['что у команды', 'общие ресурсы', 'где командный запас', 'хватит ли железа'], 'team_storage — общий запас команды, из которого оплачивается строительство.', ['team']),
    (['как взаимодействовать', 'что делает кнопка E', 'как открыть постройку', 'не могу использовать склад'], 'Подойди к постройке, наведи на неё указатель и нажми E, чтобы открыть доступные действия.', ['controls','building']),
    (['что делать дальше', 'какой следующий шаг', 'дай подсказку', 'помоги с прогрессом'], 'Следующий шаг зависит от team_storage, кислорода и построек; сначала найди текущее узкое место по данным состояния.', ['strategy']),
    (['расскажи про марс', 'что это за планета', 'где мы находимся', 'цель экспедиции'], 'Это игровая экспедиция на стилизованном Марсе: команда добывает ресурсы, строит инфраструктуру и повышает уровень кислорода.', ['intro']),
]
PREFIXES = ['', 'марсик ', 'подскажи ', 'объясни ', 'можешь сказать ']
SUFFIXES = ['', '?', ' пожалуйста', ' в этой игре', ' для нашей команды', ' сейчас', ' коротко', ' подробнее', ' я запутался', ' что делать']

items = []
for (questions, answer, tags), prefix, suffix in product(CARDS, PREFIXES, SUFFIXES):
    question = questions[(len(items) // len(SUFFIXES)) % len(questions)]
    items.append({'question': (prefix + question + suffix).strip(), 'answer': answer, 'tags': tags})

target = Path(__file__).resolve().parents[1] / 'content' / 'knowledge' / 'expedition_examples.json'
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text(json.dumps({'version': 1, 'examples': items[:1000]}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'wrote {min(1000, len(items))} examples to {target}')
